452	    /**
453	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
454	     * rolled forward, just as a weekend is, to the next non-holiday business day.
455	     */
456	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
457	        LocalDate.of(2026, 1, 1),
458	        LocalDate.of(2026, 1, 26),
459	        LocalDate.of(2026, 4, 25),
460	        LocalDate.of(2026, 12, 25),
461	        LocalDate.of(2026, 12, 28));
462	
463	    /**
464	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
465	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
466	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
467	     * registration date (whether supplied in the request or defaulted to the server date), so every
468	     * value derived from the registration date sees the adjusted business day.
469	     */
470	    private static LocalDate toBusinessDay(LocalDate date) {
471	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
472	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
473	                || PUBLIC_HOLIDAYS.contains(date)) {
474	            date = date.plusDays(1);
475	        }
476	        return date;
477	    }
