479	    /**
480	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
481	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
482	     * lower-cased so that last names are compared case-insensitively.
483	     */
484	    private static String normalizeHousehold(String value) {
485	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
486	    }
487	
488	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
489	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
490	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
491	
492	    /**
493	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
494	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
495	     * upper-cased, and common street-type abbreviations are expanded token-by-token
496	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
497	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
498	     * used for every address comparison (household-duplicate detection and the shared household id).
499	     */
500	    private static String normalizeAddress(String value) {
501	        if (value == null) {
502	            return "";
503	        }
504	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
505	        if (collapsed.isEmpty()) {
506	            return "";
507	        }
508	        String[] tokens = collapsed.split(" ");
509	        StringBuilder sb = new StringBuilder();
510	        for (int i = 0; i < tokens.length; i++) {
511	            if (i > 0) {
512	                sb.append(' ');
513	            }
514	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
515	        }
516	        return sb.toString();
517	    }
