519	    /**
520	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
521	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
522	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
523	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
524	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
525	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
526	     * The resulting {@code address} is the effective value every address reader sees, and is blank
527	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
528	     */
529	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
530	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
531	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
532	        if (!isBlank(line1)) {
533	            ownerFieldsDto.setAddressLine1(line1);
534	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
535	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
536	        } else {
537	            ownerFieldsDto.setAddressLine1(null);
538	            ownerFieldsDto.setAddressLine2(null);
539	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
540	        }
541	    }
