543	    /**
544	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
545	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
546	     * deterministic function of the normalized last name and postcode, so every owner that shares
547	     * those values maps to the same identifier regardless of creation order. A {@code null}
548	     * postcode contributes the empty string.
549	     */
550	    private static String householdId(String normalizedLastName, String postcode) {
551	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
552	        return sha256Hex12(key);
553	    }
