555	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
556	    private static String sha256Hex12(String s) {
557	        try {
558	            byte[] digest = MessageDigest.getInstance("SHA-256")
559	                .digest(s.getBytes(StandardCharsets.UTF_8));
560	            StringBuilder sb = new StringBuilder(12);
561	            for (int i = 0; i < 6; i++) {
562	                sb.append(String.format("%02x", digest[i]));
563	            }
564	            return sb.toString();
565	        }
566	        catch (NoSuchAlgorithmException e) {
567	            throw new IllegalStateException("SHA-256 not available", e);
568	        }
569	    }
