596	    /**
597	     * Builds the {@code memberId} assigned to a new owner, formatted
598	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region code derived from the owner's
599	     * postcode ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}); {@code FY} is the two-digit
600	     * fiscal year of the business-day-adjusted registration date (the fiscal year starts on 1 July);
601	     * {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the owner's normalized
602	     * E.164 telephone concatenated with the last name; and {@code CHK} is a single Luhn check digit
603	     * over the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D4'}). No sequence
604	     * number is used, so the id is a pure function of the owner's own identity fields.
605	     */
606	    private static String memberId(String postcode, String telephone, String lastName,
607	                                   LocalDate registrationDate) {
608	        String region = LocalityDeriver.region(postcode);
609	        String fiscalYear = String.format("%02d",
610	            FiscalYearDeriver.fiscalYear(registrationDate) % 100);
611	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
612	            + (lastName == null ? "" : lastName));
613	        String base = region + fiscalYear + hash8;
614	        return base + CheckDigitDeriver.checkDigit(base);
615	    }
616	
617	    /**
618	     * De-duplicates a computed {@code memberId} against the ids already assigned to existing owners.
619	     * If {@code base} is not currently in use it is returned unchanged; otherwise {@code '-<n>'} is
620	     * appended with the smallest {@code n} of 2 or more that yields an id no existing owner holds
621	     * (e.g. a second collision on {@code 'NSW261A2B3C4D4'} becomes {@code 'NSW261A2B3C4D4-2'}, a
622	     * third {@code 'NSW261A2B3C4D4-3'}, and so on).
623	     */
624	    private String deduplicateMemberId(String base) {
625	        Set<String> existing = this.clinicService.findAllOwners().stream()
626	            .map(Owner::getMemberId)
627	            .filter(id -> id != null)
628	            .collect(Collectors.toSet());
629	        if (!existing.contains(base)) {
630	            return base;
631	        }
632	        int n = 2;
633	        while (existing.contains(base + "-" + n)) {
634	            n++;
635	        }
636	        return base + "-" + n;
637	    }
638	
639	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
640	    private static String sha256Hex8(String s) {
641	        try {
642	            byte[] digest = MessageDigest.getInstance("SHA-256")
643	                .digest(s.getBytes(StandardCharsets.UTF_8));
644	            StringBuilder sb = new StringBuilder(8);
645	            for (int i = 0; i < 4; i++) {
646	                sb.append(String.format("%02X", digest[i]));
647	            }
648	            return sb.toString();
649	        }
650	        catch (NoSuchAlgorithmException e) {
651	            throw new IllegalStateException("SHA-256 not available", e);
652	        }
653	    }
