655	    /**
656	     * Counts the existing owners that share the given first name and last name, compared
657	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
658	     * owner currently being created is saved), so it reflects how many namesakes preceded the
659	     * new owner.
660	     */
661	    private int countNamesakes(String firstName, String lastName) {
662	        return (int) this.clinicService.findAllOwners().stream()
663	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
664	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
665	            .count();
666	    }
