668	    /**
669	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
670	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
671	     * national one, a single leading {@code '0'} is dropped, and the default country code
672	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
673	     * national number must have the length required by its country code ({@code '+61'} requires 9
674	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
675	     * raised (reported to the client as 400).
676	     */
677	    private static String toE164(String telephone) {
678	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
679	        String digits;
680	        if (cleaned.startsWith("+")) {
681	            digits = cleaned.substring(1);
682	        } else {
683	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
684	            digits = "61" + national;
685	        }
686	        if (!digits.matches("[0-9]{8,15}")) {
687	            throw new InvalidTelephoneException(
688	                "telephone must form a valid E.164 number with 8 to 15 digits");
689	        }
690	        validateNationalLength(digits);
691	        return "+" + digits;
692	    }
693	
694	    /** National-number length required for each supported country code (digits after the code). */
695	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
696	        "61", 9, "1", 10);
697	
698	    /**
699	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
700	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
701	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
702	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
703	     */
704	    private static void validateNationalLength(String digits) {
705	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
706	            String code = entry.getKey();
707	            if (digits.startsWith(code)) {
708	                int nationalLength = digits.length() - code.length();
709	                if (nationalLength != entry.getValue()) {
710	                    throw new InvalidTelephoneException(
711	                        "telephone national number must have " + entry.getValue()
712	                            + " digits for country code +" + code);
713	                }
714	                return;
715	            }
716	        }
717	    }
