719	    /**
720	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
721	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
722	     * any 4-digit postcode.
723	     */
724	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
725	        "NSW", new int[] {2000, 2099},
726	        "VIC", new int[] {3000, 3099},
727	        "QLD", new int[] {4000, 4099});
728	
729	    /**
730	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
731	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
732	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
733	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
734	     * no known region accepts any 4-digit postcode. A violation raises an
735	     * {@link InvalidPostcodeException} (reported to the client as 400).
736	     */
737	    private static void validatePostcode(String city, String postcode) {
738	        if (isBlank(postcode)) {
739	            return;
740	        }
741	        if (!postcode.matches("[0-9]{4}")) {
742	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
743	        }
744	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
745	        if (range == null) {
746	            return;
747	        }
748	        int value = Integer.parseInt(postcode);
749	        if (value < range[0] || value > range[1]) {
750	            throw new InvalidPostcodeException(
751	                "postcode is out of range for the owner's city region");
752	        }
753	    }
754	
755	    /**
756	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
757	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
758	     * check).
759	     */
760	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
761	        "mailinator.com", "tempmail.com", "guerrillamail.com");
762	
763	    /**
764	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
765	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
766	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
767	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
768	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
769	     * so it is stored and returned in canonical form.
770	     */
771	    private static String normalizeEmail(String email) {
772	        if (isBlank(email)) {
773	            return null;
774	        }
775	        String trimmed = email.trim();
776	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
777	            throw new InvalidEmailException("email must be a syntactically valid address");
778	        }
779	        String normalized = trimmed.toLowerCase(Locale.ROOT);
780	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
781	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
782	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
783	        }
784	        return normalized;
785	    }
786	}
